import { readFileSync, writeFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

import { bsVersion } from '../src/bs_version';

// GENERATED BY gg_version WriteVersionFile - DO NOT EDIT.
//
// Repairs the version literal in
// src/bs_version.ts
// when it drifts from package.json. Drift is not an error here: the literal
// is rewritten and the test passes.

describe('bs_version.ts', () => {
  it('matches the version in package.json', () => {
    const manifest = JSON.parse(
      readFileSync('package.json', 'utf8'),
    ) as { version?: string };
    expect(manifest.version).toBeTruthy();

    const declaration = 'export const bsVersion = ';
    const expected = `${declaration}'${manifest.version}';`;
    const path = 'src/bs_version.ts';

    if (!readFileSync(path, 'utf8').includes(expected)) {
      writeFileSync(
        path,
        readFileSync(path, 'utf8').replace(
          new RegExp(`${declaration}'[^']*';`),
          expected,
        ),
      );
    }

    expect(readFileSync(path, 'utf8')).toContain(expected);
    expect(bsVersion).toBeTruthy();
  });
});
